"""Recursive relational algorithms on a diamond-shaped dependency graph."""
from _draft_helpers import topic

S = """
CREATE TABLE node(name TEXT PRIMARY KEY);
INSERT INTO node VALUES('A'),('B'),('C'),('D'),('E'),('F');
CREATE TABLE edge(src TEXT,dst TEXT,qty INTEGER,cost INTEGER,PRIMARY KEY(src,dst));
INSERT INTO edge VALUES('A','B',2,4),('A','C',1,1),('B','D',3,2),('C','D',1,1),('D','E',1,3);
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"graph",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(172,"graph-reachability","去重递归计算图的可达节点",["递归 UNION","图可达性","菱形路径"],
   "A 经 B 或 C 都可到 D，再到 E；递归 UNION 对节点去重，所以 D、E 各只出现一次。递归行只含节点，不含递增深度，因此有限图即使有环也能因去重终止。F 无边连接，不能从 A 到达。",
   "WITH RECURSIVE reach(n) AS(SELECT dst FROM edge WHERE src='A' UNION SELECT e.dst FROM edge e JOIN reach r ON e.src=r.n) SELECT n FROM reach ORDER BY n;","B\nC\nD\nE",
   ["把路径或深度加入去重行后，环路可能不断产生新行。","UNION 去重不能用于需要保留路径数量的任务。"],
   ("列出从 C 可达的节点。","改变起点但保持递归去重。","WITH RECURSIVE r(n) AS(SELECT dst FROM edge WHERE src='C' UNION SELECT e.dst FROM edge e JOIN r ON e.src=r.n) SELECT n FROM r ORDER BY n;","D\nE"),
   ("列出从 A 不可达且不是 A 的节点。","以完整 node 表减去可达集。","WITH RECURSIVE r(n) AS(VALUES('A') UNION SELECT e.dst FROM edge e JOIN r ON e.src=r.n) SELECT name FROM node WHERE name NOT IN(SELECT n FROM r) ORDER BY name;","F")),
 T(173,"graph-path-enumeration","保留菱形图的所有路径",["UNION ALL","路径枚举","多父节点"],
   "UNION ALL 保留通往同一节点的不同路径，字符串逐段追加节点。到 E 的两条路径分别经过 B 和 C，不能按终点去重。示例是有向无环图，真实图需增加环路检查和深度上限，路径数量可能指数增长。",
   "WITH RECURSIVE p(n,path) AS(VALUES('A','A') UNION ALL SELECT e.dst,p.path||'>'||e.dst FROM p JOIN edge e ON e.src=p.n) SELECT path FROM p WHERE n='E' ORDER BY path;","A>B>D>E\nA>C>D>E",
   ["路径枚举可能指数增长，不适合无界大图。","真实含环图必须增加终止保护。"],
   ("统计到达 D 的不同路径数。","递归保留各路径后筛选终点。","WITH RECURSIVE p(n) AS(VALUES('A') UNION ALL SELECT e.dst FROM p JOIN edge e ON e.src=p.n) SELECT count(*) FROM p WHERE n='D';","2"),
   ("只输出从 A 到叶子 E 的节点数量。","沿递归维护路径长度。","WITH RECURSIVE p(n,len) AS(VALUES('A',1) UNION ALL SELECT e.dst,len+1 FROM p JOIN edge e ON e.src=p.n) SELECT DISTINCT len FROM p WHERE n='E';","4")),
 T(174,"bill-of-materials","物料清单沿路径相乘再合并",["BOM","递归乘法","需求汇总"],
   "生产一个 A 需要 2 个 B 和 1 个 C；B 各需 3 个 D，C 需 1 个 D，因此 D 总需 7、E 也需 7。递归先沿每条路径相乘，最后按物料求和。若提前按终点去重，会丢掉共享部件的需求。",
   "WITH RECURSIVE bom(n,units) AS(VALUES('A',1) UNION ALL SELECT e.dst,b.units*e.qty FROM bom b JOIN edge e ON e.src=b.n) SELECT n,sum(units) FROM bom WHERE n<>'A' GROUP BY n ORDER BY n;","B|2\nC|1\nD|7\nE|7",
   ["路径需求是相乘，平行路径需求才相加。","整数溢出和循环 BOM 需要额外防护。"],
   ("生产两个 A 时需要多少 E。","初始需求为 2。","WITH RECURSIVE b(n,q) AS(VALUES('A',2) UNION ALL SELECT e.dst,b.q*e.qty FROM b JOIN edge e ON e.src=b.n) SELECT sum(q) FROM b WHERE n='E';","14"),
   ("生产一个 B 时列出下游需求。","以 B 和数量 1 为起点。","WITH RECURSIVE b(n,q) AS(VALUES('B',1) UNION ALL SELECT e.dst,b.q*e.qty FROM b JOIN edge e ON e.src=b.n) SELECT n,sum(q) FROM b WHERE n<>'B' GROUP BY n ORDER BY n;","D|3\nE|3")),
 T(175,"graph-leaf-isolated","区分叶子节点和孤立节点",["度数","NOT EXISTS","孤立点"],
   "没有出边的节点包含 E 和 F，但只有 E 有入边，F 完全孤立。用两个独立 EXISTS 判断入度与出度，避免连接两份边表造成乘法行数。分类有助于查找终端任务与未接入工作流的配置。",
   "SELECT n.name,CASE WHEN EXISTS(SELECT 1 FROM edge e WHERE e.dst=n.name) THEN 'leaf' ELSE 'isolated' END FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge e WHERE e.src=n.name) ORDER BY n.name;","E|leaf\nF|isolated",
   ["无出边不等于有实际依赖关系的叶子。","同时连接入边和出边会放大度数。"],
   ("只返回完全孤立的节点。","既无入边也无出边。","SELECT name FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge WHERE src=n.name OR dst=n.name) ORDER BY name;","F"),
   ("找出同时有入边和出边的内部节点。","两个 EXISTS 条件使用 AND。","SELECT name FROM node n WHERE EXISTS(SELECT 1 FROM edge WHERE dst=n.name) AND EXISTS(SELECT 1 FROM edge WHERE src=n.name) ORDER BY name;","B\nC\nD")),
 T(176,"graph-roots","找出依赖图的所有起始节点",["根节点","入度","任务入口"],
   "根节点没有入边，A 与孤立的 F 都符合。若只查询有出边的 A，就会漏掉单节点任务。输出出边数量让调用方决定是否把孤立点当作独立工作流入口，避免在 SQL 层隐含业务假设。",
   "SELECT n.name,(SELECT count(*) FROM edge e WHERE e.src=n.name) children FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge e WHERE e.dst=n.name) ORDER BY n.name;","A|2\nF|0",
   ["有向环中的连通分量可能没有根。","根集合的定义是否包含孤立点需要明确。"],
   ("只返回有实际出边的根。","无入边且有出边。","SELECT name FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge WHERE dst=n.name) AND EXISTS(SELECT 1 FROM edge WHERE src=n.name) ORDER BY name;","A"),
   ("返回每个节点的直接前置依赖数量。","相关计数不会放大节点。","SELECT name,(SELECT count(*) FROM edge WHERE dst=n.name) FROM node n ORDER BY name;","A|0\nB|1\nC|1\nD|2\nE|1\nF|0")),
 T(177,"graph-ancestors","反向递归追踪全部上游依赖",["反向遍历","祖先","影响分析"],
   "从 E 沿 dst 反查 src，可以找到 D、B、C、A。递归 UNION 合并共享祖先 A，输出每个上游节点一次。查询方向与下游影响分析相反，适合解释一个任务为什么依赖某资源。",
   "WITH RECURSIVE a(n) AS(SELECT src FROM edge WHERE dst='E' UNION SELECT e.src FROM edge e JOIN a ON e.dst=a.n) SELECT n FROM a ORDER BY n;","A\nB\nC\nD",
   ["反向遍历应交换连接方向，不能只改变起点。","本节点是否计入祖先集合必须明确。"],
   ("列出 D 的直接父节点。","不递归，只查一跳。","SELECT src FROM edge WHERE dst='D' ORDER BY src;","B\nC"),
   ("列出 B 的所有祖先。","沿入边递归。","WITH RECURSIVE a(n) AS(SELECT src FROM edge WHERE dst='B' UNION SELECT e.src FROM edge e JOIN a ON e.dst=a.n) SELECT n FROM a ORDER BY n;","A")),
 T(178,"dag-depth-range","多路径图计算最浅与最深层级",["深度","路径聚合","有向无环图"],
   "在 DAG 中维护从 A 出发的边数，再对同一节点取 MIN 和 MAX。本图到 D 的两条路径都长 2，到 E 都长 3，因此两种深度相同。其他图中同节点可能有不同深度，不能把第一次访问当作唯一层级。",
   "WITH RECURSIVE p(n,depth) AS(VALUES('A',0) UNION ALL SELECT e.dst,depth+1 FROM p JOIN edge e ON e.src=p.n) SELECT n,min(depth),max(depth) FROM p GROUP BY n ORDER BY n;","A|0|0\nB|1|1\nC|1|1\nD|2|2\nE|3|3",
   ["路径深度与节点主键不是同一个去重维度。","含环时递增深度不会自行终止。"],
   ("返回距离 A 恰好两条边的节点去重集合。","递归到有限深度 2。","WITH RECURSIVE p(n,d) AS(VALUES('A',0) UNION ALL SELECT e.dst,d+1 FROM p JOIN edge e ON e.src=p.n WHERE d<2) SELECT DISTINCT n FROM p WHERE d=2 ORDER BY n;","D"),
   ("计算 A 到 E 的最大边数。","对到达 E 的路径深度取 MAX。","WITH RECURSIVE p(n,d) AS(VALUES('A',0) UNION ALL SELECT e.dst,d+1 FROM p JOIN edge e ON e.src=p.n) SELECT max(d) FROM p WHERE n='E';","3")),
 T(179,"undirected-component","忽略方向求节点所在连通分量",["双向边","连通分量","递归去重"],
   "先把每条边正反各列一次，再从 C 去重递归。这样可沿反向到 A、B，再到 D、E，得到 A 至 E；F 不连通。方向忽略只适用于物理连接或同组分析，不适合推断有向依赖的先后关系。",
   "WITH RECURSIVE und(a,b) AS(SELECT src,dst FROM edge UNION SELECT dst,src FROM edge),r(n) AS(VALUES('C') UNION SELECT u.b FROM und u JOIN r ON u.a=r.n) SELECT n FROM r ORDER BY n;","A\nB\nC\nD\nE",
   ["忽略方向会改变业务语义。","使用 UNION 去重，否则双向边立即形成无限往返。"],
   ("从孤立节点 F 求连通分量。","保留种子节点本身。","WITH RECURSIVE und(a,b) AS(SELECT src,dst FROM edge UNION SELECT dst,src FROM edge),r(n) AS(VALUES('F') UNION SELECT b FROM und JOIN r ON a=r.n) SELECT n FROM r ORDER BY n;","F"),
   ("统计 C 所在无向连通分量的节点数。","递归节点去重后 COUNT。","WITH RECURSIVE und(a,b) AS(SELECT src,dst FROM edge UNION SELECT dst,src FROM edge),r(n) AS(VALUES('C') UNION SELECT b FROM und JOIN r ON a=r.n) SELECT count(*) FROM r;","5")),
 T(180,"cycle-safe-simple-path","带访问路径保护的简单路径枚举",["环路保护","INSTR","简单路径"],
   "给图额外加入 E 到 B 的回边后，递归前检查带分隔符的访问路径，禁止重复节点。到 E 仍只有经 B 或 C 的两条简单路径，不会不断绕环。分隔符要求节点名本身不包含同一分隔符，真实标识应编码。",
   "WITH RECURSIVE g(a,b) AS(SELECT src,dst FROM edge UNION ALL SELECT 'E','B'),p(n,path) AS(VALUES('A','/A/') UNION ALL SELECT g.b,path||g.b||'/' FROM p JOIN g ON g.a=p.n WHERE instr(path,'/'||g.b||'/')=0) SELECT path FROM p WHERE n='E' ORDER BY path;","/A/B/D/E/\n/A/C/D/E/",
   ["不带分隔符会把 A 与 AA 错判为同一节点。","简单路径枚举仍可能指数增长。"],
   ("加入回边后求 A 可达节点数量。","只保留节点的 UNION 可自动去重。","WITH RECURSIVE g(a,b) AS(SELECT src,dst FROM edge UNION ALL SELECT 'E','B'),r(n) AS(VALUES('A') UNION SELECT b FROM g JOIN r ON a=r.n) SELECT count(*) FROM r;","5"),
   ("列出原图中直接进入 E 的边起点。","基准图尚未持久化添加回边。","SELECT src FROM edge WHERE dst='E' ORDER BY src;","D")),
 T(181,"cycle-witness","返回闭环路径作为依赖错误证据",["环检测","证据路径","递归停止"],
   "从 B 开始，加上 E 到 B 的回边，递归允许记录一次重复节点并标记 closed，随后停止延伸。唯一闭环见证为 /B/D/E/B/。返回路径比单个布尔值更有利于在离线配置中定位循环依赖。",
   "WITH RECURSIVE g(a,b) AS(SELECT src,dst FROM edge UNION ALL SELECT 'E','B'),p(n,path,closed) AS(VALUES('B','/B/',0) UNION ALL SELECT g.b,path||g.b||'/',instr(path,'/'||g.b||'/')>0 FROM p JOIN g ON g.a=p.n WHERE closed=0) SELECT path FROM p WHERE closed=1 ORDER BY path;","/B/D/E/B/",
   ["标记闭环后必须停止该分支。","单一起点不能证明整张图无环。"],
   ("判断原始图是否存在自环。","直接检查 src=dst。","SELECT count(*) FROM edge WHERE src=dst;","0"),
   ("加入回边后列出所有处在环中的节点。","传递闭包中起点可达自己表示位于循环。","WITH RECURSIVE g(a,b) AS(SELECT src,dst FROM edge UNION ALL SELECT 'E','B'),c(a,b) AS(SELECT a,b FROM g UNION SELECT c.a,g.b FROM c JOIN g ON g.a=c.b) SELECT a FROM c WHERE a=b ORDER BY a;","B\nD\nE")),
 T(182,"dag-processing-levels","按最长依赖深度生成执行层",["DAG 分层","依赖顺序","MAX 深度"],
   "从所有无入边根出发枚举路径，节点层级取最大深度，保证每条前置边都从较低层走向较高层。A 与独立 F 在第 0 层，B、C 在第 1 层，D 在第 2 层，E 在第 3 层。此法要求图已确认无环。",
   "WITH RECURSIVE p(n,d) AS(SELECT name,0 FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge WHERE dst=n.name) UNION ALL SELECT e.dst,p.d+1 FROM p JOIN edge e ON e.src=p.n) SELECT n,max(d) level FROM p GROUP BY n ORDER BY level,n;","A|0\nF|0\nB|1\nC|1\nD|2\nE|3",
   ["无根的环会完全缺席，必须先做环检测。","同层任务能否并发还取决于外部资源约束。"],
   ("返回所有前置依赖已经在 done 集合 A 中的待办节点。","排除 done，本节点的全部父节点必须已完成。","WITH done(n) AS(VALUES('A')) SELECT name FROM node n WHERE name NOT IN(SELECT n FROM done) AND NOT EXISTS(SELECT 1 FROM edge e WHERE e.dst=n.name AND e.src NOT IN(SELECT n FROM done)) ORDER BY name;","B\nC\nF"),
   ("只返回依赖数量超过一个的节点。","按目标节点统计入边。","SELECT dst,count(*) FROM edge GROUP BY dst HAVING count(*)>1 ORDER BY dst;","D|2")),
 T(183,"weighted-path-cost","枚举有界 DAG 路径求最小费用",["加权路径","MIN","路径代价"],
   "每经过一条边累加 cost，最后按终点取 MIN。到 D 经 C 费用 2，小于经 B 的 6；到 E 的最小费用为 5。此处枚举完整 DAG 路径，并非可扩展的 Dijkstra 实现，大图要使用专门算法或强边界。",
   "WITH RECURSIVE p(n,cost) AS(VALUES('A',0) UNION ALL SELECT e.dst,p.cost+e.cost FROM p JOIN edge e ON e.src=p.n) SELECT n,min(cost) FROM p GROUP BY n ORDER BY n;","A|0\nB|4\nC|1\nD|2\nE|5",
   ["有负环时最小费用可能没有下界。","该枚举方法在路径多时成本很高。"],
   ("计算从 A 到 E 的最高路径费用。","对所有到 E 的费用取 MAX。","WITH RECURSIVE p(n,c) AS(VALUES('A',0) UNION ALL SELECT e.dst,c+e.cost FROM p JOIN edge e ON e.src=p.n) SELECT max(c) FROM p WHERE n='E';","9"),
   ("列出直接边中单位数量成本最高的边。","cost 乘 1.0 再除 qty。","SELECT src,dst,cost*1.0/qty FROM edge ORDER BY cost*1.0/qty DESC,src,dst LIMIT 1;","D|E|3.0")),
 T(184,"graph-transitive-closure","一次构造全部祖先后代对",["传递闭包","复合去重","影响范围"],
   "递归行保存起点和当前终点，UNION 对节点对去重。A 可到四个节点、B 和 C 各可到两个、D 可到一个，共九对。可缓存闭包加速影响查询，但边变更后要处理失效，不能把旧缓存当实时图。",
   "WITH RECURSIVE closure(a,b) AS(SELECT src,dst FROM edge UNION SELECT c.a,e.dst FROM closure c JOIN edge e ON e.src=c.b) SELECT a,b FROM closure ORDER BY a,b;","A|B\nA|C\nA|D\nA|E\nB|D\nB|E\nC|D\nC|E\nD|E",
   ["闭包最大可接近节点数的平方。","自可达是否包含空路径需要明确。"],
   ("统计每个有后代节点的后代数量。","闭包按起点分组。","WITH RECURSIVE c(a,b) AS(SELECT src,dst FROM edge UNION SELECT c.a,e.dst FROM c JOIN edge e ON e.src=c.b) SELECT a,count(*) FROM c GROUP BY a ORDER BY a;","A|4\nB|2\nC|2\nD|1"),
   ("求既是 A 后代又是 E 祖先的中间节点。","闭包自连接查双向条件。","WITH RECURSIVE c(a,b) AS(SELECT src,dst FROM edge UNION SELECT c.a,e.dst FROM c JOIN edge e ON e.src=c.b) SELECT x.b FROM c x JOIN c y ON y.a=x.b WHERE x.a='A' AND y.b='E' ORDER BY x.b;","B\nC\nD")),
 T(185,"graph-shared-dependencies","两项任务共享的下游部件",["集合交集","依赖分析","INTERSECT"],
   "分别从 B 与 C 递归，求后代交集，得到 D 和 E。这与比较直接子节点不同，E 虽不是 B、C 的直接孩子，却是共享的间接依赖。该集合适合评估共享部件故障的影响。",
   "WITH RECURSIVE b(n) AS(SELECT dst FROM edge WHERE src='B' UNION SELECT e.dst FROM edge e JOIN b ON e.src=b.n),c(n) AS(SELECT dst FROM edge WHERE src='C' UNION SELECT e.dst FROM edge e JOIN c ON e.src=c.n) SELECT n FROM b INTERSECT SELECT n FROM c ORDER BY n;","D\nE",
   ["共享直接边与共享传递依赖不是同一口径。","INTERSECT 返回去重集合。"],
   ("求 B 和 C 共同的直接孩子。","两个直接目标集合求交。","SELECT dst FROM edge WHERE src='B' INTERSECT SELECT dst FROM edge WHERE src='C' ORDER BY dst;","D"),
   ("找出 A 的直接孩子中同样依赖 D 的节点。","查找两跳路径。","SELECT a.dst FROM edge a JOIN edge b ON b.src=a.dst WHERE a.src='A' AND b.dst='D' ORDER BY a.dst;","B\nC")),
 T(186,"graph-terminal-demand","只汇总终端物料需求",["叶子过滤","BOM","最终需求"],
   "BOM 递归结果包含中间件和终端件，若直接求总数会混加不同层次。仅保留没有出边的物料，本例只需采购 E 共 7 个；孤立 F 没被 A 使用，不能自动加入采购。",
   "WITH RECURSIVE b(n,q) AS(VALUES('A',1) UNION ALL SELECT e.dst,b.q*e.qty FROM b JOIN edge e ON e.src=b.n) SELECT n,sum(q) FROM b WHERE NOT EXISTS(SELECT 1 FROM edge WHERE src=b.n) GROUP BY n ORDER BY n;","E|7",
   ["中间组件数量与最终原料数量不能混加。","采购还应扣除库存，本课只计算毛需求。"],
   ("从 C 出发计算终端毛需求。","种子换成 C，数量为 1。","WITH RECURSIVE b(n,q) AS(VALUES('C',1) UNION ALL SELECT e.dst,b.q*e.qty FROM b JOIN edge e ON e.src=b.n) SELECT n,sum(q) FROM b WHERE NOT EXISTS(SELECT 1 FROM edge WHERE src=b.n) GROUP BY n ORDER BY n;","E|1"),
   ("找出不被任何 BOM 引用的节点。","按无入边条件查询。","SELECT name FROM node n WHERE NOT EXISTS(SELECT 1 FROM edge WHERE dst=n.name) ORDER BY name;","A\nF")),
]
